import { useEffect, useState } from "react";
import adminService from "../../services/adminService";
import StaffUserFormModal from "../../components/admin/StaffUserFormModal";
import Loader from "../../components/common/Loader";
import ErrorAlert from "../../components/common/ErrorAlert";
import ConfirmModal from "../../components/common/ConfirmModal";
import { formatDateOnly } from "../../utils/formatters";
import { notifyError, notifySuccess } from "../../utils/toast";

const ROLE_FILTERS = ["ALL", "ADMIN", "PHARMACIST", "CUSTOMER"];

export default function Users() {
  const [users, setUsers] = useState([]);
  const [roleFilter, setRoleFilter] = useState("ALL");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [pendingToggle, setPendingToggle] = useState(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [creating, setCreating] = useState(false);

  const load = async () => {
    setLoading(true);
    setError("");
    try {
      const data = await adminService.getAllUsers();
      setUsers(data);
    } catch (err) {
      setError(err.friendlyMessage);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const confirmToggle = async () => {
    const { userId, active } = pendingToggle;
    try {
      await adminService.setUserActiveStatus(userId, !active);
      setUsers((prev) => prev.map((u) => (u.userId === userId ? { ...u, active: !active } : u)));
      notifySuccess(!active ? "User activated" : "User deactivated");
    } catch (err) {
      notifyError(err.friendlyMessage);
    } finally {
      setPendingToggle(null);
    }
  };

  const handleCreateStaff = async (data) => {
    setCreating(true);
    try {
      const created = await adminService.createStaffUser(data);
      setUsers((prev) => [created, ...prev]);
      notifySuccess(`${created.role === "ADMIN" ? "Admin" : "Pharmacist"} account created for ${created.email}`);
      setShowCreateForm(false);
    } catch (err) {
      notifyError(err.friendlyMessage);
    } finally {
      setCreating(false);
    }
  };

  if (loading) return <Loader />;
  if (error) return <ErrorAlert message={error} onRetry={load} />;

  const filtered = roleFilter === "ALL" ? users : users.filter((u) => u.role === roleFilter);

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h4 className="mb-0">Users</h4>
        <div className="d-flex gap-2">
          <select className="form-select" style={{ maxWidth: "200px" }} value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)}>
            {ROLE_FILTERS.map((r) => (
              <option key={r} value={r}>{r === "ALL" ? "All Roles" : r}</option>
            ))}
          </select>
          <button className="btn btn-primary text-nowrap" onClick={() => setShowCreateForm(true)}>
            <i className="bi bi-person-plus me-1" /> Add Staff
          </button>
        </div>
      </div>

      <div className="table-responsive">
        <table className="table table-hover align-middle bg-white shadow-sm rounded">
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Phone</th>
              <th>Role</th>
              <th>Joined</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((user) => (
              <tr key={user.userId}>
                <td>{user.firstName} {user.lastName}</td>
                <td>{user.email}</td>
                <td>{user.phone || "-"}</td>
                <td><span className="badge bg-light text-dark border">{user.role}</span></td>
                <td>{formatDateOnly(user.createdAt)}</td>
                <td>
                  <span className={`badge ${user.active ? "bg-success-subtle text-success-emphasis" : "bg-danger-subtle text-danger-emphasis"}`}>
                    {user.active ? "Active" : "Inactive"}
                  </span>
                </td>
                <td>
                  <button
                    className={`btn btn-sm ${user.active ? "btn-outline-danger" : "btn-outline-success"}`}
                    onClick={() => setPendingToggle(user)}
                  >
                    {user.active ? "Deactivate" : "Activate"}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <StaffUserFormModal
        show={showCreateForm}
        submitting={creating}
        onSubmit={handleCreateStaff}
        onCancel={() => setShowCreateForm(false)}
      />

      <ConfirmModal
        show={!!pendingToggle}
        title={pendingToggle?.active ? "Deactivate User" : "Activate User"}
        message={`${pendingToggle?.active ? "Deactivate" : "Activate"} ${pendingToggle?.firstName} ${pendingToggle?.lastName}'s account?`}
        confirmLabel={pendingToggle?.active ? "Deactivate" : "Activate"}
        confirmVariant={pendingToggle?.active ? "danger" : "success"}
        onConfirm={confirmToggle}
        onCancel={() => setPendingToggle(null)}
      />
    </div>
  );
}
